const out = $json.output || {};
const results = Array.isArray(out.results) ? out.results : [];
const cand = $('Build itch Claude Input').first().json.candidates || [];
const z = $now.setZone('Europe/Berlin');
const day = z.toFormat('yyyy-LL-dd');
const sentAt = $now.toISO();
const esc = s => (s||'').toString().replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const outItems = [];
for (const c of cand) {
  const r = results.find(x => x && x.idx === c.idx) || {};
  const used = r.used_ai === true;
  const title = (r.title || c.title || '').toString().trim();
  const note = (r.ai_note || '').toString().trim();
  const safeUrl = (c.url||'').toString().replace(/&/g,'&amp;').replace(/"/g,'%22');
  const message = used ? ('🎮 itch.io · <b>' + esc(title) + '</b>\n\n' + esc(note) + '\n\n🔗 <a href="' + safeUrl + '">Source</a>') : '';
  outItems.push({ json: { url: c.url, title, used_ai: used, ai_note: note, day, sent_at: sentAt, message } });
}
return outItems;

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36';
const items = $input.all().map(i => i.json);
const getImg = async (it) => {
  let image = '';
  try { const r = await this.helpers.httpRequest({ url: it.url, returnFullResponse: true, timeout: 8000, headers: { 'User-Agent': UA } }); const b = (r.body||'').toString(); const m = b.match(/<meta[^>]+property="og:image"[^>]+content="([^"]+)"/i) || b.match(/<meta[^>]+content="([^"]+)"[^>]+property="og:image"/i) || b.match(/<meta[^>]+name="twitter:image(?::src)?"[^>]+content="([^"]+)"/i); image = m ? m[1] : ''; } catch (e) {}
  return Object.assign({}, it, { image });
};
const out = [];
const CONC = 8;
for (let i = 0; i < items.length; i += CONC) { const ch = items.slice(i, i + CONC); const res = await Promise.all(ch.map(getImg)); for (const r of res) out.push({ json: r }); }
return out;

// Parse Claude JSON note -> Google Docs batchUpdate requests (Gemini-style layout)
const __c = ($("claude-sonnet-4-6").item.json.content || []); const raw = (((__c.find(b=>b&&b.type==="text")||__c[0]||{}).text) || "").trim();
let j;
try {
  const a = raw.indexOf("{"), b = raw.lastIndexOf("}");
  j = JSON.parse(raw.slice(a, b + 1));
} catch (err) {
  j = { title: "Заметка", summary_intro: raw, summary_sections: [], decisions_aligned: [], decisions_open: [], next_steps: [], details: [] };
}

const z = $now.setZone("Europe/Berlin");
const dateStr = z.toFormat("dd.LL.yyyy");
const titleText = (j.title || "Заметка").toString().trim() || "Заметка";

const C_HEAD = { red: 0.122, green: 0.122, blue: 0.122 };
const C_BODY = { red: 0.188, green: 0.188, blue: 0.188 };
const C_CHIP = { red: 0.824, green: 0.890, blue: 0.988 };

let text = "";
const paras = [];
const bullets = [];
const runs = [];

function heading(str, named, size) {
  const s = text.length; text += str + "\n"; const e = text.length;
  paras.push({ start: s, end: e, named: named });
  runs.push({ start: s, end: e - 1, bold: true, size: size, fg: C_HEAD });
}
function bodyPara(str) {
  const s = text.length; text += str + "\n"; const e = text.length;
  runs.push({ start: s, end: e - 1, size: 11, fg: C_BODY });
}
function leadPara(lead, rest, preset) {
  const s = text.length; text += lead; const le = text.length;
  text += rest + "\n"; const e = text.length;
  runs.push({ start: s, end: le, bold: true, size: 11, fg: C_BODY });
  if (rest) runs.push({ start: le, end: e - 1, size: 11, fg: C_BODY });
  if (preset) bullets.push({ start: s, end: e, preset: preset });
}

// TITLE
{
  const s = text.length; text += "🎙 " + titleText + "\n"; const e = text.length;
  paras.push({ start: s, end: e, named: "HEADING_2" });
  runs.push({ start: s, end: e - 1, bold: true, size: 26, fg: C_HEAD });
}
// DATE chip
{
  const s = text.length; text += dateStr; const e = text.length; text += "\n";
  runs.push({ start: s, end: e, size: 11, fg: C_HEAD, bg: C_CHIP });
}
text += "\n";

// SUMMARY
heading("Summary", "HEADING_3", 20);
if (j.summary_intro) bodyPara(j.summary_intro.toString().trim());
(j.summary_sections || []).filter(Boolean).forEach(function (sec) {
  leadPara((sec.heading || "").toString().trim() + "  ", (sec.text || "").toString().trim(), null);
});

// DECISIONS
const da = (j.decisions_aligned || []).filter(Boolean);
const dop = (j.decisions_open || []).filter(Boolean);
if (da.length || dop.length) {
  heading("Decisions", "HEADING_3", 20);
  if (dop.length) {
    heading("Needs Further Discussion", "SUBTITLE", 14);
    dop.forEach(function (d) { leadPara((d.title || "").toString().trim() + "  ", (d.desc || "").toString().trim(), "BULLET_DISC_CIRCLE_SQUARE"); });
  }
  if (da.length) {
    heading("Aligned", "SUBTITLE", 14);
    da.forEach(function (d) { leadPara((d.title || "").toString().trim() + "  ", (d.desc || "").toString().trim(), "BULLET_DISC_CIRCLE_SQUARE"); });
  }
}

// NEXT STEPS
const ns = (j.next_steps || []).filter(Boolean);
if (ns.length) {
  heading("Next steps", "HEADING_3", 20);
  ns.forEach(function (n) {
    const owner = (n.owner || "").toString().trim();
    const ttl = (n.title || "").toString().trim();
    const task = (n.task || "").toString().trim();
    const lead = (owner ? ("[" + owner + "] ") : "") + ttl + (task ? ": " : "");
    leadPara(lead, task, "BULLET_CHECKBOX");
  });
}

// DETAILS
const det = (j.details || []).filter(Boolean);
if (det.length) {
  heading("Details", "HEADING_3", 20);
  det.forEach(function (d) { leadPara((d.topic || "").toString().trim() + ": ", (d.text || "").toString().trim(), "BULLET_DISC_CIRCLE_SQUARE"); });
}

// QUOTES (always last)
const qs = (j.quotes || []).filter(Boolean);
if (qs.length) {
  heading("Quotes", "HEADING_3", 20);
  qs.forEach(function (q) {
    const quote = (q.quote || "").toString().trim();
    if (!quote) return;
    const author = (q.author || "").toString().trim();
    const s = text.length;
    text += "«" + quote + "»";
    const qe = text.length;
    if (author) text += " — " + author;
    text += "\n";
    const e = text.length;
    runs.push({ start: s, end: qe, italic: true, size: 11, fg: C_BODY });
    if (author) runs.push({ start: qe, end: e - 1, size: 11, fg: C_BODY });
    bullets.push({ start: s, end: e, preset: "BULLET_DISC_CIRCLE_SQUARE" });
  });
}


// FULL TRANSCRIPTION - verbatim, numbered, always last
var _tr = $("Get Draft For Save").all().map(function(i){ return (i.json.transcript||"").toString().trim(); }).filter(Boolean);
if (_tr.length) {
  heading("🎙 Full transcript", "HEADING_3", 20);
  _tr.forEach(function(t, i){ bodyPara((i+1) + ". " + t); });
}

// Build requests (Docs index = textOffset + 1; insertText first, then bullets, paragraph styles, global font, per-run)
const reqs = [];
reqs.push({ insertText: { location: { index: 1 }, text: text } });
bullets.forEach(function (b) {
  reqs.push({ createParagraphBullets: { range: { startIndex: b.start + 1, endIndex: b.end + 1 }, bulletPreset: b.preset } });
});
paras.forEach(function (p) {
  reqs.push({ updateParagraphStyle: { range: { startIndex: p.start + 1, endIndex: p.end + 1 }, paragraphStyle: { namedStyleType: p.named }, fields: "namedStyleType" } });
});
reqs.push({ updateTextStyle: { range: { startIndex: 1, endIndex: text.length + 1 }, textStyle: { weightedFontFamily: { fontFamily: "Google Sans Flex Normal" } }, fields: "weightedFontFamily" } });
runs.forEach(function (r) {
  if (r.end <= r.start) return;
  const ts = {}; let fields = "";
  function addf(name) { fields += (fields ? "," : "") + name; }
  if (r.bold) { ts.bold = true; addf("bold"); }
  if (r.italic) { ts.italic = true; addf("italic"); }
  if (r.size) { ts.fontSize = { magnitude: r.size, unit: "PT" }; addf("fontSize"); }
  if (r.fg) { ts.foregroundColor = { color: { rgbColor: r.fg } }; addf("foregroundColor"); }
  if (r.bg) { ts.backgroundColor = { color: { rgbColor: r.bg } }; addf("backgroundColor"); }
  if (!fields) return;
  reqs.push({ updateTextStyle: { range: { startIndex: r.start + 1, endIndex: r.end + 1 }, textStyle: ts, fields: fields } });
});

const docTitle = titleText + " — " + z.toFormat("yyyy/LL/dd HH:mm") + " CEST — Notes by Tryll";
return [{ json: { documentTitle: docTitle, requests: reqs } }];

