// The n8n code sandbox has no URL class, so URLs are parsed by hand.
function parseUrl(u) {
  const m = String(u || '').trim().match(/^[a-z][a-z0-9+.-]*:\/\/([^\/?#]+)([^?#]*)(\?[^#]*)?/i);
  if (!m) return null;
  return { host: m[1].toLowerCase().replace(/:\d+$/, ''), path: m[2] || '', query: (m[3] || '').slice(1) };
}
function normUrl(u) {
  const p = parseUrl(u);
  if (!p) {
    let s = String(u || '').trim().toLowerCase().split('#')[0];
    while (s.endsWith('/')) s = s.slice(0, -1);
    return s;
  }
  const host = p.host.replace(/^(www|m|amp)\./, '');
  let path = p.path.replace(/\/amp\/?$/i, '');
  while (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
  if (path === '/') path = '';
  const q = p.query.split('&').filter(kv => kv && !/^(utm_[^=]*|fbclid|gclid|ref|ref_src|source|mc_cid|mc_eid|cmpid|oc)(=|$)/i.test(kv)).join('&');
  return (host + path + (q ? '?' + q : '')).toLowerCase();
}
function cleanTitle(t) { return String(t || '').replace(/\s+[-–—|]\s+[^-–—|]{2,40}$/, '').trim(); }
function tokens(t) {
  return cleanTitle(t).toLowerCase().replace(/[’'`]/g, '')
    .split(/[^a-z0-9а-яё.+]+/i)
    .map(w => w.replace(/^[.+]+|[.+]+$/g, ''))
    .filter(w => w && (w.length >= 3 || /\d/.test(w)) && !STOP.has(w));
}
function versions(t) { return new Set(String(t || '').toLowerCase().match(/\d+(?:\.\d+)+/g) || []); }
function sameVersions(a, b) {
  const A = versions(a), B = versions(b);
  if (!A.size || !B.size) return true;
  if (A.size !== B.size) return false;
  for (const x of A) if (!B.has(x)) return false;
  return true;
}
function jacc(a, b) {
  const A = new Set(a), B = new Set(b);
  if (!A.size || !B.size) return 0;
  let i = 0;
  for (const x of A) if (B.has(x)) i++;
  return i / (A.size + B.size - i);
}
function isJunk(u) {
  const p = parseUrl(u);
  if (!p) return true;
  const host = p.host.replace(/^www\./, '');
  if (host === 'theopenweights.com') return true;
  const segs = p.path.split('/').filter(Boolean);
  if (segs.length === 0) return true;
  if (segs.length === 1 && /^(blog|news|press|newsroom|articles?|updates?|changelog|releases|posts|insights|resources|research|en|en-us)$/i.test(segs[0])) return true;
  return false;
}
