    for (const b of (r.content || [])) if (b && b.type === 'text') text += b.text;
    const a = text.indexOf('{'), z = text.lastIndexOf('}');
    const j = JSON.parse(text.slice(a, z + 1));
    for (const v of (j.results || [])) if (v && v.idx !== undefined && v.idx !== null) verdicts[Number(v.idx)] = v;
  } catch (e) { /* judge failed: URL + title checks still apply */ }
}

const nowIso = $now.toISO();
const nowMs = Date.now();
const H48 = 48 * 3600000;
const FOLLOW_DAYS = { 'competitor': 30, 'local-model': 14 };
const items = prep.items.map(x => Object.assign({}, x, { extra_urls: [] }));
const byIdx = {};
items.forEach(x => { byIdx[x.idx] = x; });

for (const it of items) {
  if (it.pre === 'junk' || it.pre === 'dup_url') { it.action = 'skip'; continue; }
  if (it.pre === 'dup_title') { it.action = 'append'; continue; }
  if (it.pre === 'dup_batch') { it.action = 'merge'; continue; }
  const v = verdicts[it.idx];
  const verdict = v ? String(v.verdict || '').toUpperCase() : 'NEW';
  if (verdict === 'SAME') {
    if (byId[v.story_id]) { it.action = 'append'; it.story_id = v.story_id; } else it.action = 'skip';
    continue;
  }
  if (verdict === 'DUP') {
    const d = Number(v.dup_of_idx);
    if (!isNaN(d) && byIdx[d] && d < it.idx) { it.action = 'merge'; it.dup_of_idx = d; } else it.action = 'skip';
    continue;
  }
  if (verdict === 'UPDATE') {
    const s = byId[v.story_id];
    if (!s) { it.action = 'skip'; continue; }
    const first = Date.parse(s.first_sent || '');
    const last = Date.parse(s.last_update || s.first_sent || '');
    const follow = (FOLLOW_DAYS[s.bucket] || 30) * 86400000;
    if (!isNaN(first) && nowMs - first > follow) { it.action = 'new'; continue; }
    if (!isNaN(last) && nowMs - last < H48) { it.action = 'append'; it.story_id = v.story_id; continue; }
    it.action = 'update'; it.story_id = v.story_id; it.update_note = String(v.update_note || '').trim();
    continue;
  }
  it.action = 'new';
}

function resolve(it, depth) {
  if (!it || depth > 20) return null;
  if (it.action !== 'merge') return it;
  return resolve(byIdx[it.dup_of_idx], depth + 1);
}
for (const it of items) {
  if (it.action !== 'merge') continue;
  const t = resolve(byIdx[it.dup_of_idx], 0);
  if (t && t.action === 'new') { t.extra_urls.push(it.nurl); it.action = 'skip'; }
  else if (t && (t.action === 'append' || t.action === 'update') && t.story_id) { it.action = 'append'; it.story_id = t.story_id; }
  else it.action = 'skip';
}

const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const dry = items.some(i => i.dry_run);
const appendMap = {};
function addUrls(sid, urls) {
  if (!byId[sid]) return;
  if (!appendMap[sid]) appendMap[sid] = new Set(String(byId[sid].urls || '').split('|').filter(Boolean));
  for (const u of urls) if (u) appendMap[sid].add(u);
}
for (const it of items) if (it.action === 'append') addUrls(it.story_id, [it.nurl]);

const out = [];
let n = 0;
for (const it of items) {
  if (it.action === 'new') {
    const sid = 'S' + nowMs.toString(36) + '-' + (n++);
    const urls = [it.nurl].concat(it.extra_urls).filter((u, i, a) => u && a.indexOf(u) === i);
    const when = it.dry_run && it.sent_at ? it.sent_at : nowIso;
    const row = {
      story_id: sid, entity: it.entity || '', bucket: it.bucket || '', branch: it.branch || '',
      headline: it.title || '', summary: it.summary || '', url: it.url || '', urls: urls.join('|'),
      fingerprint: it.fp || '', tg_message_id: '', first_sent: when, last_update: when, updates: 0, last_note: '',
    };
    const route = it.dry_run ? 'dry' : (it.photo === 'og' ? 'post_photo' : 'post_text');
    out.push({ json: Object.assign({}, it, { route, row }) });
  } else if (it.action === 'update') {
    const s = byId[it.story_id];
    addUrls(it.story_id, [it.nurl]);
    const day = String(it.date || nowIso).slice(0, 10);
    const ent = it.entity || s.entity || '';
    const safeUrl = String(it.url || '').replace(/&/g, '&amp;').replace(/"/g, '%22');
    const message = '🔄 <b>UPDATE</b>' + (ent ? ' · ' + esc(ent) : '') + ' · ' + esc(day)
      + '\n<b>' + esc(it.title) + '</b>\n\n' + esc(it.update_note || it.summary || '')
      + '\n\n🔗 <a href="' + safeUrl + '">Source</a>';
    const reply = /^\d+$/.test(String(s.tg_message_id || '')) ? Number(s.tg_message_id) : 0;
    const route = it.dry_run ? 'dry' : (reply ? 'upd_reply' : 'upd_plain');
    const upd = { story_id: it.story_id, urls: String(s.urls || ''), last_update: nowIso, updates: Number(s.updates || 0) + 1, last_note: it.update_note || '' };
    out.push({ json: Object.assign({}, it, { route, reply_to: reply, message, upd }) });
  } else if (it.dry_run) {
    out.push({ json: Object.assign({}, it, { route: 'dry' }) });
  }
}
if (!dry) {
  for (const sid of Object.keys(appendMap)) {
    const s = byId[sid];
    const urls = [...appendMap[sid]].join('|');
    const updItems = out.filter(o => o.json.upd && o.json.story_id === sid);
    if (updItems.length) { updItems.forEach(o => { o.json.upd.urls = urls; }); continue; }
    if (urls === String(s.urls || '')) continue;
    out.push({ json: { route: 'append', story_id: sid, urls, last_update: s.last_update || '', updates: Number(s.updates || 0), last_note: s.last_note || '' } });
  }
}
return out;

// Story row for each posted photo card, with the Telegram message id.
