// News filter request for Claude Sonnet 5 (replaces the old LangChain chain).
const bi = $json;
const SYSTEM = `You are the senior market-intelligence curator for Tryll Engine, a startup building ON-DEVICE AI middleware for GAMES: LLM/voice AI NPCs, speech-to-text, text-to-speech, and generative game content that run LOCALLY on the player's own GPU (no cloud, no per-call cost). Plugins for Unity / Unreal / Godot.

Your job: from the candidate feed items, keep ONLY the few a Tryll founder MUST see. Be ruthless. Contrast over coverage. When in doubt, REJECT.

KEEP (keep=true) ONLY if the item fits ONE of these four buckets; set "industry" to that bucket's key:

1. "ai-in-games": AI / on-device AI actually used IN games: AI NPCs, voice/conversational characters, local inference in a game, generative in-game content, AI tooling for Unity/Unreal/Godot, engine AI features (NVIDIA ACE/NVIGI, Unreal NNE, Unity AI). Must be AI-in-a-game, not a plain game.

2. "competitor": a move by a company on our COMPETITOR list: product/plugin/model/demo release, partnership, integration, notable technical post, or a game adopting their tech. COMPETITORS: Inworld AI, Convai, Glade / GladeCore / Glade Studio, Player2 (Elefant AI), Artificial Agency, GeorgyDev, UndreamAI (LLM for Unity), Charisma.ai, HakkoAI, Bitpart AI, Studio Atelico, NVIDIA ACE/NVIGI, Microsoft Copilot for Gaming, Google Gemini Live (gaming), Unity AI, Unreal NNE / Epic, Ubisoft Teammates, Varco Game AI (NCSoft), Getnamo (Llama-Unreal), RunAnywhere, ClawdBot / MoltBot, Iconic Games, Parametrix AI, Aura, Run Edge AI, Bezi, Rosebud AI, Codewisp.

3. "local-model": a FRESH model for TEXT->TEXT, SPEECH->TEXT (STT/ASR) or TEXT->SPEECH (TTS) with OPEN, DOWNLOADABLE WEIGHTS from a serious lab (Google/DeepMind, Alibaba Qwen, Meta, Mistral, Microsoft, NVIDIA, DeepSeek, Kyutai, Moonshot/Kimi, Kokoro, Nari (Dia), Coqui, Zhipu/GLM, Tencent, ByteDance, Xiaomi). The item itself must show the weights are downloadable (Hugging Face, GitHub, "open weights", "open source" with a license). Cloud-only or API-only models (new Gemini, GPT, Claude or ElevenLabs API models, etc.) are NOT local-model: reject them unless they clearly fit another bucket.

4. "research": substantive research (paper or lab blog) on AI in games OR on-device/local models (for example a DeepMind post on game-playing agents, an efficient on-device TTS paper).

REJECT (keep=false) EVERYTHING ELSE, no exceptions:
- funding / investment / raises / valuations / M&A (even in AI or games);
- layoffs, studio closures, furloughs, hiring, exec moves;
- ordinary game releases, trailers, reviews, delays, sales, hardware/consoles;
- consumer gadgets, phones, laptops, TVs, appliances;
- generic AI news with NO tie to games or on-device inference (chatbots, enterprise AI, policy, lawsuits, safety drama, regulation);
- mass-media, opinion, listicles, roundups, marketing;
- anything that repeats a story in ALREADY_SENT.
If two candidates are the same event, keep only the most authoritative one.

For EVERY candidate return: idx; keep; industry; entity (the main company, product or model the item is about, e.g. "Unity AI", "Qwen3.8-27B"; "" when keep=false); title (ORIGINAL, unchanged); summary_ru.
- summary_ru: ONLY for keep=true: a sharp ENGLISH 1-2 sentence take on WHAT happened and WHY it matters to an on-device-AI-for-games company (<=300 chars). For keep=false use "".
- NEVER put reasoning or verdict words into title or summary_ru.

Output ONLY JSON, one entry per candidate:
{"results":[{"idx":0,"keep":false,"industry":"","entity":"","title":"...","summary_ru":""}]}`;
const user = 'ALREADY_SENT (recent stories, do not repeat):\n' + JSON.stringify(bi.recent_sent || [])
  + '\n\nCANDIDATES:\n' + JSON.stringify(bi.candidates || []) + '\n\nReturn ONLY the JSON object.';
return [{ json: { request_body: {
  model: 'claude-sonnet-5', max_tokens: 16000, output_config: { effort: 'medium' },
  system: SYSTEM, messages: [{ role: 'user', content: user }],
} } }];

// Fresh open-weight repos straight from the Hugging Face API (no web search, exact ids and dates).
const ORGS = ['Qwen', 'google', 'meta-llama', 'mistralai', 'microsoft', 'nvidia', 'deepseek-ai', 'zai-org', 'moonshotai', 'tencent',
  'ByteDance-Seed', 'kyutai', 'hexgrad', 'nari-labs', 'fishaudio', 'SparkAudio', 'XiaomiMiMo', 'internlm', 'ibm-granite', 'allenai',
  'HuggingFaceTB', 'openai', 'stepfun-ai', 'MiniMaxAI', 'baidu', 'LiquidAI', 'CohereLabs', 'FunAudioLLM', 'openbmb', 'apple',
  'facebook', 'ResembleAI', 'canopylabs', 'sesame'];
const TASKS = new Set(['text-generation', 'text2text-generation', 'image-text-to-text', 'any-to-any', 'automatic-speech-recognition',
  'text-to-speech', 'text-to-audio', 'audio-text-to-text', 'audio-to-audio']);
const SKIP = /(gguf|awq|gptq|fp8|nvfp4|mxfp4|int4|int8|w4a16|w8a8|mlx|onnx|bnb|4bit|8bit|exl2|eagle|lora|adapter|reward|-prm\b|draft)/i;
const cutoff = Date.now() - 7 * 86400000;
const repos = [];
for (let i = 0; i < ORGS.length; i += 6) {
  const chunk = ORGS.slice(i, i + 6);
  const res = await Promise.all(chunk.map(async org => {
    try {
      const arr = await this.helpers.httpRequest({ url: 'https://huggingface.co/api/models?author=' + encodeURIComponent(org) + '&sort=createdAt&direction=-1&limit=40', json: true, timeout: 20000 });
      return { org, arr: Array.isArray(arr) ? arr : [] };
    } catch (e) { return { org, arr: [] }; }
  }));
  for (const { org, arr } of res) {
    for (const m of arr) {
      const t = Date.parse(m.createdAt || '');
      if (isNaN(t) || t < cutoff) continue;
      const id = String(m.id || m.modelId || '');
      if (!id || SKIP.test(id) || m.private) continue;
      const task = m.pipeline_tag || '';
      if (task && !TASKS.has(task)) continue;
      repos.push({
        id, org, created: new Date(t).toISOString().slice(0, 10), task: task || 'unknown',
        likes: m.likes || 0, downloads: m.downloads || 0,
        tags: (m.tags || []).filter(x => !/^(region|arxiv|base_model|dataset|endpoints|autotrain|deploy|doi)/.test(x)).slice(0, 12),
      });
    }
  }
}
if (!repos.length) return [];
return [{ json: { repos } }];

// Evening digest from the shared story memory: today's new stories plus today's updates.
const rows = ($json.rows || []).filter(r => r && r.story_id);
const tz = 'Europe/Berlin';
const today = $now.setZone(tz).toFormat('yyyy-LL-dd');
const dayOf = iso => { if (!iso) return ''; const d = DateTime.fromISO(String(iso)); return d.isValid ? d.setZone(tz).toFormat('yyyy-LL-dd') : String(iso).slice(0, 10); };
const fresh = rows.filter(r => dayOf(r.first_sent) === today);
const upd = rows.filter(r => Number(r.updates || 0) > 0 && dayOf(r.last_update) === today && dayOf(r.first_sent) !== today);
if (!fresh.length && !upd.length) return [];
const items = fresh.map(r => ({ kind: 'new', bucket: r.bucket, entity: r.entity, title: r.headline, gist: r.summary, url: r.url }))
  .concat(upd.map(r => ({ kind: 'update', bucket: r.bucket, entity: r.entity, title: r.headline, gist: r.last_note, url: r.url })));
const system = `You write the evening digest for the Tryll Engine team's Telegram news topic (Tryll Engine: on-device AI middleware for games). Write in English. Use ONLY Telegram HTML tags b, i, a. Replace every & in text with &amp;.

Format:
- First line: exactly the HEADER line given in the input.
- Then these sections in this order, only when they have items, each heading on its own line: 🎮 <b>AI in games</b> (bucket ai-in-games), 🎯 <b>Competitors</b> (competitor), 🧠 <b>Local models</b> (local-model), 🔬 <b>Research</b> (research), 📡 <b>Other</b> (anything else), 🔄 <b>Updates</b> (kind "update" items only go here).
- Each item: one line "• <b>short title</b> — gist in 6-12 words — <a href="URL">site</a>", where site is the domain name of the URL.
- No intro, no outro, nothing else.`;
const date = $now.setZone(tz).toFormat('dd.LL.yyyy');
const header = '<b>Daily digest — ' + date + '</b> · ' + fresh.length + (fresh.length === 1 ? ' story' : ' stories') + (upd.length ? ' · ' + upd.length + (upd.length === 1 ? ' update' : ' updates') : '');
const user = 'HEADER: ' + header + '\nITEMS:\n' + JSON.stringify(items);
return [{ json: { request_body: {
  model: 'claude-sonnet-5', max_tokens: 4000, output_config: { effort: 'low' },
  system, messages: [{ role: 'user', content: user }],
} } }];

// Digest text from the Claude answer (skips thinking blocks).
let t = '';
for (const b of ($json.content || [])) if (b && b.type === 'text') t += b.text;
t = t.trim();
if (!t) return [];
return [{ json: { text: t } }];

// Weekly health report: which feeds are dead or quiet, and what the news topic posted this week.
const sources = $('Health Sources').all().map(i => i.json).filter(s => s && s.active === true && s.feed_url);
const stories = $input.all().map(i => i.json).filter(s => s && s.story_id);
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36';
const DAY = 86400000, now = Date.now();
const res = [];
for (let i = 0; i < sources.length; i += 8) {
  const chunk = sources.slice(i, i + 8);
  const r = await Promise.all(chunk.map(async s => {
    try {
      const x = await this.helpers.httpRequest({ url: s.feed_url, returnFullResponse: true, timeout: 20000, headers: { 'User-Agent': UA } });
      const b = String(x.body || '');
      const n = (b.match(/<item[\s>]/gi) || []).length || (b.match(/<entry[\s>]/gi) || []).length;
      const ds = (b.match(/<(pubDate|published|updated)[^>]*>[^<]+</gi) || [])
        .map(m => Date.parse(m.replace(/<[^>]+>/g, '').replace(/<$/, '').trim())).filter(t => !isNaN(t));
      return { name: s.name, n, newest: ds.length ? Math.max(...ds) : 0, err: n ? '' : 'no items' };
    } catch (e) {
      const code = e && (e.httpCode || (e.response && e.response.status) || e.statusCode);
      return { name: s.name, n: 0, newest: 0, err: code ? 'HTTP ' + code : String((e && e.message) || e).slice(0, 40) };
    }
  }));
  res.push(...r);
}
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const dead = res.filter(r => r.err);
const quiet = res.filter(r => !r.err && r.newest && now - r.newest > 30 * DAY);
const ok = res.length - dead.length;
const weekNew = stories.filter(s => now - Date.parse(s.first_sent || '') <= 7 * DAY);
const weekUpd = stories.filter(s => Number(s.updates || 0) > 0 && now - Date.parse(s.last_update || '') <= 7 * DAY);
const byBucket = {};
for (const s of weekNew) byBucket[s.bucket || 'other'] = (byBucket[s.bucket || 'other'] || 0) + 1;
const lines = [];
lines.push('🩺 <b>News bot health</b> · ' + $now.setZone('Europe/Berlin').toFormat('dd.LL.yyyy'));
lines.push('Feeds OK: ' + ok + '/' + res.length);
if (dead.length) lines.push('❌ Not working: ' + dead.map(d => esc(d.name) + ' (' + esc(d.err) + ')').join(', '));
if (quiet.length) lines.push('💤 Quiet for 30+ days: ' + quiet.map(q => esc(q.name)).join(', '));
lines.push('Posted this week: ' + weekNew.length + ' stories' + (weekUpd.length ? ', ' + weekUpd.length + ' updated' : ''));
const parts = Object.keys(byBucket).sort().map(k => k + ' ' + byBucket[k]);
if (parts.length) lines.push('By topic: ' + parts.join(' · '));
return [{ json: { message: lines.join('\n') } }];
